using System.Runtime.InteropServices;
using Windows.Win32;
using Windows.Win32.Foundation;
using Windows.Win32.UI.Accessibility;

namespace AppLock.Services;

public class WinEventHookService : IDisposable
{
    // Win32 event constants (not generated by CsWin32)
    private const uint EVENT_OBJECT_SHOW = 0x8002;
    private const uint EVENT_SYSTEM_FOREGROUND = 0x0003;
    private const uint EVENT_OBJECT_LOCATIONCHANGE = 0x800B;
    private const uint EVENT_OBJECT_DESTROY = 0x8001;
    private const uint EVENT_SYSTEM_MINIMIZEEND = 0x0017;
    private const uint WINEVENT_OUTOFCONTEXT = 0x0000;
    
    private HWINEVENTHOOK _showHook;
    private HWINEVENTHOOK _focusHook;
    private HWINEVENTHOOK _moveHook;
    private HWINEVENTHOOK _destroyHook;
    private HWINEVENTHOOK _minimizeEndHook;
    
    private readonly WINEVENTPROC _eventCallback;
    
    public event EventHandler<WindowEventArgs>? WindowShown;
    public event EventHandler<WindowEventArgs>? WindowFocused;
    public event EventHandler<WindowEventArgs>? WindowMoved;
    public event EventHandler<WindowEventArgs>? WindowDestroyed;
    public event EventHandler<WindowEventArgs>? WindowRestored;

    public WinEventHookService()
    {
        // Keep delegate alive to prevent GC
        _eventCallback = new WINEVENTPROC(WinEventProc);
    }

    public void Start()
    {
        uint currentProcessId = PInvoke.GetCurrentProcessId();

        // Hook for window shown
        _showHook = PInvoke.SetWinEventHook(
            EVENT_OBJECT_SHOW,
            EVENT_OBJECT_SHOW,
            HMODULE.Null,
            _eventCallback,
            0,
            0,
            WINEVENT_OUTOFCONTEXT);

        // Hook for window focused
        _focusHook = PInvoke.SetWinEventHook(
            EVENT_SYSTEM_FOREGROUND,
            EVENT_SYSTEM_FOREGROUND,
            HMODULE.Null,
            _eventCallback,
            0,
            0,
            WINEVENT_OUTOFCONTEXT);

        // Hook for window moved/resized
        _moveHook = PInvoke.SetWinEventHook(
            EVENT_OBJECT_LOCATIONCHANGE,
            EVENT_OBJECT_LOCATIONCHANGE,
            HMODULE.Null,
            _eventCallback,
            0,
            0,
            WINEVENT_OUTOFCONTEXT);

        // Hook for window destroyed
        _destroyHook = PInvoke.SetWinEventHook(
            EVENT_OBJECT_DESTROY,
            EVENT_OBJECT_DESTROY,
            HMODULE.Null,
            _eventCallback,
            0,
            0,
            WINEVENT_OUTOFCONTEXT);

        // Hook for window restored from minimize
        _minimizeEndHook = PInvoke.SetWinEventHook(
            EVENT_SYSTEM_MINIMIZEEND,
            EVENT_SYSTEM_MINIMIZEEND,
            HMODULE.Null,
            _eventCallback,
            0,
            0,
            WINEVENT_OUTOFCONTEXT);
    }

    private void WinEventProc(HWINEVENTHOOK hWinEventHook, uint eventType, HWND hwnd, int idObject, int idChild, uint idEventThread, uint dwmsEventTime)
    {
        if (hwnd.IsNull || idObject != 0 || idChild != 0)
            return;

        var args = new WindowEventArgs { WindowHandle = (nint)hwnd.Value };

        switch (eventType)
        {
            case EVENT_OBJECT_SHOW:
                WindowShown?.Invoke(this, args);
                break;
            case EVENT_SYSTEM_FOREGROUND:
                WindowFocused?.Invoke(this, args);
                break;
            case EVENT_OBJECT_LOCATIONCHANGE:
                WindowMoved?.Invoke(this, args);
                break;
            case EVENT_OBJECT_DESTROY:
                WindowDestroyed?.Invoke(this, args);
                break;
            case EVENT_SYSTEM_MINIMIZEEND:
                WindowRestored?.Invoke(this, args);
                break;
        }
    }

    public void Stop()
    {
        if (!_showHook.IsNull)
            PInvoke.UnhookWinEvent(_showHook);
        if (!_focusHook.IsNull)
            PInvoke.UnhookWinEvent(_focusHook);
        if (!_moveHook.IsNull)
            PInvoke.UnhookWinEvent(_moveHook);
        if (!_destroyHook.IsNull)
            PInvoke.UnhookWinEvent(_destroyHook);
        if (!_minimizeEndHook.IsNull)
            PInvoke.UnhookWinEvent(_minimizeEndHook);
    }

    public void Dispose()
    {
        Stop();
        GC.SuppressFinalize(this);
    }
}

public class WindowEventArgs : EventArgs
{
    public nint WindowHandle { get; set; }
}
